# Functional version of the sales processing pipeline
from functools import reduce
from collections import defaultdict

# Tax rates as given in the original imperative version
_TAX_RATES = {'US': 0.08, 'EU': 0.20, 'UK': 0.20, 'JP': 0.10}
_DEFAULT_TAX_RATE = 0.15


def process_sales_functional(records):
    """Process sales records functionally.

    Steps:
    1. Filter out refunds and non‑positive amounts.
    2. Apply regional tax rates and compute total.
    3. Group records by region.
    4. Summarise count and total per region.
    """
    # Step 1: filter
    valid = list(filter(lambda r: r['amount'] > 0 and r['status'] != 'refunded', records))

    # Step 2: apply tax
    def add_tax(r):
        rate = _TAX_RATES.get(r['region'], _DEFAULT_TAX_RATE)
        total = round(r['amount'] * (1 + rate), 2)
        # return a new dict with extra fields
        return {**r, 'total': total, 'tax_rate': rate}

    taxed = list(map(add_tax, valid))

    # Step 3: group by region using reduce
    def group_by(acc, r):
        acc[r['region']].append(r)
        return acc

    groups = reduce(group_by, taxed, defaultdict(list))

    # Step 4: compute summary per region
    summary = {
        region: {
            'count': len(items),
            'total': round(sum(item['total'] for item in items), 2)
        }
        for region, items in groups.items()
    }
    return summary

# ----- Test suite -----
import unittest

class TestProcessSalesFunctional(unittest.TestCase):
    def setUp(self):
        self.sample_records = [
            {'id': 1, 'amount': 100, 'status': 'completed', 'region': 'US'},
            {'id': 2, 'amount': 200, 'status': 'refunded', 'region': 'EU'},
            {'id': 3, 'amount': -50, 'status': 'completed', 'region': 'UK'},
            {'id': 4, 'amount': 150, 'status': 'completed', 'region': 'EU'},
            {'id': 5, 'amount': 120, 'status': 'completed', 'region': 'JP'},
            {'id': 6, 'amount': 80,  'status': 'completed', 'region': 'CA'},  # uses default tax rate
        ]
        # Expected result computed manually (same as imperative version)
        self.expected_summary = {
            'US': {'count': 1, 'total': round(100 * (1 + 0.08), 2)},
            'EU': {'count': 1, 'total': round(150 * (1 + 0.20), 2)},
            'JP': {'count': 1, 'total': round(120 * (1 + 0.10), 2)},
            'CA': {'count': 1, 'total': round(80  * (1 + 0.15), 2)},
        }

    def test_functional_output_matches_expected(self):
        result = process_sales_functional(self.sample_records)
        self.assertEqual(result, self.expected_summary)

    def test_consistency_with_imperative(self):
        # Import the imperative version defined inline for comparison
        def process_sales_imperative(records):
            valid = []
            for r in records:
                if r['amount'] > 0 and r['status'] != 'refunded':
                    valid.append(r)
            taxed = []
            tax_rates = {'US': 0.08, 'EU': 0.20, 'UK': 0.20, 'JP': 0.10}
            for r in valid:
                rate = tax_rates.get(r['region'], 0.15)
                total = r['amount'] * (1 + rate)
                taxed.append({**r, 'total': round(total, 2), 'tax_rate': rate})
            groups = {}
            for r in taxed:
                region = r['region']
                if region not in groups:
                    groups[region] = []
                groups[region].append(r)
            summary = {}
            for region, items in groups.items():
                total = 0
                for item in items:
                    total += item['total']
                summary[region] = {'count': len(items), 'total': round(total, 2)}
            return summary
        imp_result = process_sales_imperative(self.sample_records)
        func_result = process_sales_functional(self.sample_records)
        self.assertEqual(imp_result, func_result)

if __name__ == '__main__':
    unittest.main()
